def _parse(version):
    """Parse a semantic version into core parts and pre-release identifiers."""
    without_build = version.split('+', 1)[0]
    if '-' in without_build:
        core, prerelease = without_build.split('-', 1)
    else:
        core, prerelease = without_build, None

    major, minor, patch = (int(part) for part in core.split('.'))
    pre = None if prerelease is None else prerelease.split('.')
    return major, minor, patch, pre


def _compare_identifier(a, b):
    a_numeric = a.isdigit()
    b_numeric = b.isdigit()

    if a_numeric and b_numeric:
        a_value = int(a)
        b_value = int(b)
        return (a_value > b_value) - (a_value < b_value)
    if a_numeric != b_numeric:
        return -1 if a_numeric else 1

    return (a > b) - (a < b)


def _compare_versions(a, b):
    a_core = _parse(a)
    b_core = _parse(b)

    if a_core[:3] != b_core[:3]:
        return (a_core[:3] > b_core[:3]) - (a_core[:3] < b_core[:3])

    a_pre = a_core[3]
    b_pre = b_core[3]

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    for a_id, b_id in zip(a_pre, b_pre):
        comparison = _compare_identifier(a_id, b_id)
        if comparison:
            return comparison

    return (len(a_pre) > len(b_pre)) - (len(a_pre) < len(b_pre))


def sort_versions(vs):
    """Return semantic version strings sorted by SemVer precedence, stably."""
    return sorted(vs, key=cmp_to_key(_compare_versions))
